import { read, arrayReader, blobReader } from "./reader";
import { streamDecompressor, UnsupportedCompressionMethodError } from "./decompress";
export { read, streamDecompressor, UnsupportedCompressionMethodError };
// shorthands for the core API
export const readBytes = (b, options) => read(arrayReader(b), options);
export const readBlob = (b, options) => read(blobReader(b), options);
